#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> adj(N);
    for (int i = 0; i < N - 1; ++i) {
        int A, B;
        cin >> A >> B;
        --A;
        --B;
        adj[A].push_back(B);
        adj[B].push_back(A);
    }

    vector<int> parent(N, -1), order;
    order.reserve(N);
    parent[0] = 0;
    order.push_back(0);

    for (int i = 0; i < static_cast<int>(order.size()); ++i) {
        int u = order[i];
        for (int v : adj[u]) {
            if (parent[v] == -1) {
                parent[v] = u;
                order.push_back(v);
            }
        }
    }

    vector<int> subtree(N, 1);
    int answer = N;

    for (int i = N - 1; i > 0; --i) {
        int u = order[i];
        answer = min(answer, abs(N - 2 * subtree[u]));
        subtree[parent[u]] += subtree[u];
    }

    cout << answer << '\n';
    return 0;
}
